package com.example.sirh.service;

import com.example.sirh.controller.LeaveController.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@Service
public class LeaveManagementService {
    private static final Set<String> PORTIONS=Set.of("FULL","AM","PM");
    private static final Set<String> STATUSES=Set.of("en_attente","en_attente_manager","en_attente_rh","a_ajuster","approuve","refuse","annule");
    private static final Set<String> MIMES=Set.of("application/pdf","image/jpeg","image/png");
    private static final long MAX_FILE=8L*1024*1024;
    private final JdbcTemplate jdbc; private final EmployeeAccessService access; private final NationalIdCryptoService crypto; private final ZoneId zone;
    public LeaveManagementService(JdbcTemplate jdbc,EmployeeAccessService access,NationalIdCryptoService crypto,
            @Value("${sirh.time-tracking.zone-id:Europe/Paris}") String zoneId){this.jdbc=jdbc;this.access=access;this.crypto=crypto;this.zone=ZoneId.of(zoneId);}

    public List<Map<String,Object>> types(Authentication actor){requirePortalRole(actor);return jdbc.queryForList("SELECT id,name,requires_justification,requires_balance,requires_rh_approval FROM leave_types ORDER BY name");}
    public List<Map<String,Object>> balances(Integer year,Authentication actor){int employee=selfId(actor);int period=year==null?LocalDate.now().getYear():year;if(period<2000||period>2200)throw new IllegalArgumentException("Année invalide.");return jdbc.queryForList("SELECT b.leave_type_id,t.name,b.period_year,b.acquired_days,b.taken_days,b.remaining_days FROM leave_balances b JOIN leave_types t ON t.id=b.leave_type_id WHERE b.employee_id=? AND b.period_year=? ORDER BY t.name",employee,period);}
    public List<Map<String,Object>> myRequests(Authentication actor){int employee=selfId(actor);return jdbc.queryForList("SELECT r.*,t.name leave_type_name,(SELECT count(*)>0 FROM leave_request_documents d WHERE d.leave_request_id=r.id) has_document FROM leave_requests r JOIN leave_types t ON t.id=r.leave_type_id WHERE r.employee_id=? ORDER BY r.created_at DESC",employee);}
    public Map<String,Object> preview(LeaveRequestBody body,Authentication actor){int employee=selfId(actor);Validated v=validate(body,employee,null,false);return previewMap(employee,v);}

    @Transactional public Map<String,Object> submit(LeaveRequestBody body,MultipartFile file,Authentication actor){int employee=selfId(actor);lockEmployee(employee);Validated v=validate(body,employee,null,true);Map<String,Object> type=type(v.typeId());boolean requiresDoc=Boolean.TRUE.equals(type.get("requires_justification"));if(requiresDoc&&(file==null||file.isEmpty()))throw new IllegalArgumentException("Un justificatif est obligatoire pour ce type d’absence.");int id=insertRequest(employee,actor.getName(),v,requiresDoc,Boolean.TRUE.equals(type.get("requires_rh_approval")),body.reasonDetail());if(file!=null&&!file.isEmpty())storeFile(id,file,actor);return request(id,employee);}

    @Transactional public Map<String,Object> updateAdjusted(int id,LeaveRequestBody body,Authentication actor){int employee=selfId(actor);lockEmployee(employee);Map<String,Object> current=requestForUpdate(id);if(asInt(current.get("employee_id"))!=employee||!"a_ajuster".equals(current.get("status")))throw new ForbiddenOperationException("Cette demande n’est pas modifiable par ce compte.");Validated v=validate(body,employee,id,true);Map<String,Object> t=type(v.typeId());boolean doc=Boolean.TRUE.equals(t.get("requires_justification"));if(doc&&!Boolean.TRUE.equals(current.get("has_document")))throw new IllegalArgumentException("Un justificatif est toujours requis pour ce type.");jdbc.update("UPDATE leave_requests SET leave_type_id=?,start_date=?,end_date=?,start_portion=?,end_portion=?,period_start=?,period_end=?,total_business_days=?,reason_detail=?,requires_justification_snapshot=?,requires_rh_approval_snapshot=?,status='en_attente_manager',decision_note=NULL,adjustment_note=NULL,updated_at=CURRENT_TIMESTAMP WHERE id=?",v.typeId(),v.start(),v.end(),v.startPortion(),v.endPortion(),Timestamp.valueOf(v.periodStart()),Timestamp.valueOf(v.periodEnd()),v.days(),blank(body.reasonDetail()),doc,t.get("requires_rh_approval"),id);return request(id,employee);}
    @Transactional public Map<String,Object> cancel(int id,Authentication actor){int employee=selfId(actor);int n=jdbc.update("UPDATE leave_requests SET status='annule',updated_at=CURRENT_TIMESTAMP WHERE id=? AND employee_id=? AND status IN ('en_attente','en_attente_manager','a_ajuster')",id,employee);if(n!=1)throw new WorkflowConflictException("Seules les demandes en attente ou à ajuster peuvent être annulées.");return request(id,employee);}

    public List<Map<String,Object>> approvals(Authentication actor){requireApprover(actor);String sql="SELECT r.id,r.employee_id,r.leave_type_id,t.name leave_type_name,r.start_date,r.end_date,r.start_portion,r.end_portion,r.total_business_days,r.reason_detail,r.status,r.requires_justification_snapshot,r.adjustment_note,e.first_name,e.last_name,e.department_id,(SELECT count(*)>0 FROM leave_request_documents d WHERE d.leave_request_id=r.id) has_document FROM leave_requests r JOIN leave_types t ON t.id=r.leave_type_id JOIN employees e ON e.id=r.employee_id WHERE ";if(access.isManager(actor)){List<String> deps=access.managedDepartments(actor);if(deps.isEmpty())return List.of();sql+="r.status IN ('en_attente','en_attente_manager') AND e.department_id IN ("+marks(deps.size())+") ORDER BY r.created_at";return jdbc.queryForList(sql,deps.toArray());}sql+="r.status='en_attente_rh' ORDER BY r.created_at";return jdbc.queryForList(sql);}

    @Transactional public Map<String,Object> decide(int id,DecisionBody body,Authentication actor){requireApprover(actor);String decision=body.decision().toUpperCase(Locale.ROOT);if(!Set.of("APPROUVER","REFUSER","AJUSTER").contains(decision))throw new IllegalArgumentException("Décision non reconnue.");if(!"APPROUVER".equals(decision)&&(body.reason()==null||body.reason().trim().length()<5))throw new IllegalArgumentException("Un motif d’au moins 5 caractères est obligatoire.");int employee=jdbc.query("SELECT employee_id FROM leave_requests WHERE id=?",(rs,n)->rs.getInt(1),id).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Demande de congé introuvable."));checkApproverScope(employee,actor);lockEmployee(employee);Map<String,Object> request=requestForUpdate(id);String status=String.valueOf(request.get("status"));boolean isManager=access.isManager(actor);if(isManager&&!Set.of("en_attente","en_attente_manager").contains(status))throw new WorkflowConflictException("Cette demande n’attend pas la validation du manager.");if(access.isHr(actor)&&!"en_attente_rh".equals(status))throw new WorkflowConflictException("Cette demande attend d’abord la validation du manager.");
        String next;if("AJUSTER".equals(decision))next="a_ajuster";else if("REFUSER".equals(decision))next="refuse";else if(isManager&&Boolean.TRUE.equals(request.get("requires_rh_approval_snapshot")))next="en_attente_rh";else next="approuve";
        if("approuve".equals(next))debitBalance(request,actor);
        String column=isManager?"manager_reviewed_by":"rh_reviewed_by";
        jdbc.update("UPDATE leave_requests SET status=?,"+column+"=?,decision_note=?,adjustment_note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",next,actor.getName(),blank(body.reason()),"AJUSTER".equals(decision)?body.reason().trim():null,id);
        return request(id,employee);
    }

    @Transactional public Map<String,Object> accrue(AccrualBody body,Authentication actor){access.requireHr(actor);LocalDate month=body.month().withDayOfMonth(1);if(month.isAfter(LocalDate.now().withDayOfMonth(1)))throw new IllegalArgumentException("Impossible d’acquérir des droits pour un mois futur.");int employee=body.employeeId();activeEmployee(employee);String type=body.leaveTypeId();BigDecimal days=jdbc.query("SELECT monthly_days FROM leave_accrual_policies WHERE leave_type_id=?",(rs,n)->rs.getBigDecimal(1),type).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Aucune règle d’acquisition pour ce type."));if(days.signum()==0)return Map.of("employeeId",employee,"leaveTypeId",type,"month",month,"accruedDays",BigDecimal.ZERO,"alreadyApplied",true);int inserted=jdbc.update("INSERT INTO leave_accrual_ledger(employee_id,leave_type_id,accrual_month,days) VALUES(?,?,?,?) ON CONFLICT(employee_id,leave_type_id,accrual_month) DO NOTHING",employee,type,month,days);if(inserted==0)return Map.of("employeeId",employee,"leaveTypeId",type,"month",month,"accruedDays",BigDecimal.ZERO,"alreadyApplied",true);jdbc.update("INSERT INTO leave_balances(employee_id,leave_type_id,period_year,acquired_days,taken_days,remaining_days) VALUES(?,?,?, ?,0,?) ON CONFLICT(employee_id,leave_type_id,period_year) DO UPDATE SET acquired_days=leave_balances.acquired_days+EXCLUDED.acquired_days,remaining_days=leave_balances.remaining_days+EXCLUDED.remaining_days",employee,type,month.getYear(),days,days);jdbc.update("INSERT INTO leave_balance_movements(employee_id,leave_type_id,period_year,movement_type,days,created_by) VALUES(?,?,?,'ACQUIS',?,?)",employee,type,month.getYear(),days,actor.getName());return Map.of("employeeId",employee,"leaveTypeId",type,"month",month,"accruedDays",days,"alreadyApplied",false);}
    public List<Map<String,Object>> accrualPolicies(Authentication actor){access.requireHr(actor);return jdbc.queryForList("SELECT p.leave_type_id,t.name,p.monthly_days FROM leave_accrual_policies p JOIN leave_types t ON t.id=p.leave_type_id ORDER BY t.name");}
    @Transactional public List<Map<String,Object>> setAccrualPolicy(AccrualPolicyBody body,Authentication actor){access.requireHr(actor);if(body.monthlyDays().compareTo(BigDecimal.ZERO)<0||body.monthlyDays().compareTo(BigDecimal.TEN)>0)throw new IllegalArgumentException("Le droit mensuel doit être compris entre 0 et 10 jours.");type(body.leaveTypeId());jdbc.update("INSERT INTO leave_accrual_policies(leave_type_id,monthly_days,updated_by,updated_at) VALUES(?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(leave_type_id) DO UPDATE SET monthly_days=EXCLUDED.monthly_days,updated_by=EXCLUDED.updated_by,updated_at=CURRENT_TIMESTAMP",body.leaveTypeId(),body.monthlyDays(),actor.getName());return accrualPolicies(actor);}

    @Scheduled(cron="${sirh.leaves.accrual-cron:0 5 0 1 * *}",zone="${sirh.time-tracking.zone-id:Europe/Paris}")
    @Transactional public void accrueCurrentMonth(){LocalDate month=LocalDate.now(zone).withDayOfMonth(1);List<Map<String,Object>> policies=jdbc.queryForList("SELECT leave_type_id,monthly_days FROM leave_accrual_policies WHERE monthly_days>0");List<Integer> employees=jdbc.queryForList("SELECT id FROM employees WHERE status='actif' ORDER BY id",Integer.class);for(Integer employee:employees)for(Map<String,Object> policy:policies){String type=String.valueOf(policy.get("leave_type_id"));BigDecimal days=(BigDecimal)policy.get("monthly_days");applyAccrual(employee,type,month,days,null);}}
    private boolean applyAccrual(int employee,String type,LocalDate month,BigDecimal days,String actor){int inserted=jdbc.update("INSERT INTO leave_accrual_ledger(employee_id,leave_type_id,accrual_month,days) VALUES(?,?,?,?) ON CONFLICT(employee_id,leave_type_id,accrual_month) DO NOTHING",employee,type,month,days);if(inserted==0)return false;jdbc.update("INSERT INTO leave_balances(employee_id,leave_type_id,period_year,acquired_days,taken_days,remaining_days) VALUES(?,?,?, ?,0,?) ON CONFLICT(employee_id,leave_type_id,period_year) DO UPDATE SET acquired_days=leave_balances.acquired_days+EXCLUDED.acquired_days,remaining_days=leave_balances.remaining_days+EXCLUDED.remaining_days",employee,type,month.getYear(),days,days);jdbc.update("INSERT INTO leave_balance_movements(employee_id,leave_type_id,period_year,movement_type,days,created_by) VALUES(?,?,?,'ACQUIS',?,?)",employee,type,month.getYear(),days,actor);return true;}

    public Map<String,Object> calendar(Authentication actor){requirePortalRole(actor);Map<String,Object> setting=jdbc.queryForMap("SELECT counting_method,region_code,team_absence_warning_ratio FROM leave_calendar_settings WHERE id=1");setting.put("holidays",jdbc.queryForList("SELECT holiday_date,region_code,label FROM leave_public_holidays WHERE region_code=? ORDER BY holiday_date",setting.get("region_code")));return setting;}
    @Transactional public Map<String,Object> configureCalendar(CalendarBody body,Authentication actor){access.requireHr(actor);String method=body.countingMethod().toUpperCase(Locale.ROOT);String region=body.regionCode().trim().toUpperCase(Locale.ROOT);if(!Set.of("OUVRES","OUVRABLES").contains(method)||!region.matches("[A-Z0-9_-]{2,12}")||body.teamAbsenceWarningRatio().compareTo(BigDecimal.ZERO)<0||body.teamAbsenceWarningRatio().compareTo(BigDecimal.ONE)>0)throw new IllegalArgumentException("Paramètres calendrier invalides.");jdbc.update("UPDATE leave_calendar_settings SET counting_method=?,region_code=?,team_absence_warning_ratio=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=1",method,region,body.teamAbsenceWarningRatio(),actor.getName());return calendar(actor);}
    @Transactional public Map<String,Object> addHoliday(HolidayBody body,Authentication actor){access.requireHr(actor);String region=body.regionCode().trim().toUpperCase(Locale.ROOT);jdbc.update("INSERT INTO leave_public_holidays(holiday_date,region_code,label) VALUES(?,?,?) ON CONFLICT(holiday_date,region_code) DO UPDATE SET label=EXCLUDED.label",body.date(),region,body.label().trim());return calendar(actor);}
    @Transactional public void removeHoliday(LocalDate date,Authentication actor){access.requireHr(actor);String region=String.valueOf(calendar(actor).get("region_code"));jdbc.update("DELETE FROM leave_public_holidays WHERE holiday_date=? AND region_code=?",date,region);}
    public List<Map<String,Object>> teamCalendar(LocalDate from,LocalDate to,Authentication actor){requireApprover(actor);if(from.isAfter(to)||Duration.between(from.atStartOfDay(),to.plusDays(1).atStartOfDay()).toDays()>100)throw new IllegalArgumentException("Période invalide (100 jours maximum).");String sql="SELECT r.id,r.employee_id,e.first_name,e.last_name,e.department_id,t.name leave_type_name,r.start_date,r.end_date,r.start_portion,r.end_portion,r.total_business_days FROM leave_requests r JOIN employees e ON e.id=r.employee_id JOIN leave_types t ON t.id=r.leave_type_id WHERE r.status='approuve' AND r.start_date<=? AND r.end_date>=?";if(access.isManager(actor)){List<String>d=access.managedDepartments(actor);if(d.isEmpty())return List.of();sql+=" AND e.department_id IN ("+marks(d.size())+")";Object[] args=new Object[d.size()+2];args[0]=to;args[1]=from;for(int i=0;i<d.size();i++)args[i+2]=d.get(i);return jdbc.queryForList(sql+" ORDER BY r.start_date,e.last_name",args);}return jdbc.queryForList(sql+" ORDER BY r.start_date,e.last_name",to,from);}

    public LeaveFile justification(int id,Authentication actor){Map<String,Object> r=requestForUpdate(id);int employee=asInt(r.get("employee_id"));if(!access.isHr(actor)&&!(access.isEmployee(actor)&&selfId(actor)==employee))throw new ForbiddenOperationException("Le justificatif est réservé au salarié concerné et aux RH.");var rows=jdbc.query("SELECT filename,mime_type,encrypted_content FROM leave_request_documents WHERE leave_request_id=? ORDER BY created_at DESC LIMIT 1",(rs,n)->new Object[]{rs.getString(1),rs.getString(2),rs.getBytes(3)},id);if(rows.isEmpty())throw new ResourceNotFoundException("Justificatif introuvable.");Object[] f=rows.getFirst();return new LeaveFile((String)f[0],(String)f[1],crypto.decryptBytes((byte[])f[2]));}

    private Map<String,Object> previewMap(int employee,Validated v){Map<String,Object> type=type(v.typeId());BigDecimal remaining=BigDecimal.ZERO;boolean enough=true;if(Boolean.TRUE.equals(type.get("requires_balance")))for(var part:daysByYear(v).entrySet()){BigDecimal available=availableBalance(employee,v.typeId(),part.getKey(),null);remaining=remaining.add(available);if(available.compareTo(part.getValue())<0)enough=false;}List<Map<String,Object>> overlaps=overlaps(employee,v,null);Map<String,Object> team=teamImpact(employee,v);return Map.of("requestedDays",v.days(),"remainingDays",remaining,"projectedRemainingDays",remaining.subtract(Boolean.TRUE.equals(type.get("requires_balance"))?v.days():BigDecimal.ZERO),"sufficientBalance",enough,"overlap",!overlaps.isEmpty(),"overlappingRequests",overlaps,"teamImpact",team,"requiresJustification",Boolean.TRUE.equals(type.get("requires_justification")),"requiresRhApproval",Boolean.TRUE.equals(type.get("requires_rh_approval")));}
    private Validated validate(LeaveRequestBody b,int employee,Integer ignore,boolean enforce){if(b.startDate().isAfter(b.endDate()))throw new IllegalArgumentException("La date de fin doit être postérieure ou égale à la date de début.");String sp=b.startPortion().toUpperCase(Locale.ROOT),ep=b.endPortion().toUpperCase(Locale.ROOT);if(!PORTIONS.contains(sp)||!PORTIONS.contains(ep))throw new IllegalArgumentException("Période de journée invalide.");LocalDateTime start,end;if(b.startDate().equals(b.endDate())){boolean validPair=("FULL".equals(sp)&&"FULL".equals(ep))||("AM".equals(sp)&&("AM".equals(ep)||"PM".equals(ep)))||("PM".equals(sp)&&"PM".equals(ep));if(!validPair)throw new IllegalArgumentException("Pour une seule journée, choisissez journée entière, matin, après-midi ou matin à après-midi.");if("PM".equals(sp)){start=b.startDate().atTime(12,0);end=b.startDate().plusDays(1).atStartOfDay();}else if("AM".equals(ep)){start=b.startDate().atStartOfDay();end=b.startDate().atTime(12,0);}else{start=b.startDate().atStartOfDay();end=b.startDate().plusDays(1).atStartOfDay();}}
        else {start="PM".equals(sp)?b.startDate().atTime(12,0):b.startDate().atStartOfDay();end="AM".equals(ep)?b.endDate().atTime(12,0):b.endDate().plusDays(1).atStartOfDay();}
        if(!start.isBefore(end))throw new IllegalArgumentException("Période de congé invalide.");Map<String,Object> type=type(b.leaveTypeId());BigDecimal days=calculateDays(b.startDate(),b.endDate(),sp,ep);if(days.signum()<=0)throw new IllegalArgumentException("La période ne contient aucun jour de congé à décompter.");Validated validated=new Validated(b.leaveTypeId(),b.startDate(),b.endDate(),sp,ep,start,end,days);if(enforce&&Boolean.TRUE.equals(type.get("requires_balance")))for(var part:daysByYear(validated).entrySet())if(availableBalance(employee,b.leaveTypeId(),part.getKey(),ignore).compareTo(part.getValue())<0)throw new WorkflowConflictException("Le solde disponible, après réservation des demandes en attente, est insuffisant pour l’année "+part.getKey()+".");List<Map<String,Object>> conflicts=overlaps(employee,validated,ignore);if(enforce&&!conflicts.isEmpty())throw new WorkflowConflictException("Cette période chevauche une autre demande active.");return validated;}
    private BigDecimal calculateDays(LocalDate start,LocalDate end,String sp,String ep){Map<String,Object> cfg=jdbc.queryForMap("SELECT counting_method,region_code FROM leave_calendar_settings WHERE id=1");String method=String.valueOf(cfg.get("counting_method")),region=String.valueOf(cfg.get("region_code"));Set<LocalDate> holidays=new HashSet<>(jdbc.queryForList("SELECT holiday_date FROM leave_public_holidays WHERE region_code=? AND holiday_date BETWEEN ? AND ?",LocalDate.class,region,start,end));int days=0;for(LocalDate d=start;!d.isAfter(end);d=d.plusDays(1)){int day=d.getDayOfWeek().getValue();boolean working="OUVRES".equals(method)?day<=5:day<=6;if(working&&!holidays.contains(d))days++;}if(start.equals(end)){if(!isWorking(start,method,holidays))return BigDecimal.ZERO;if("FULL".equals(sp)&&"FULL".equals(ep)||"AM".equals(sp)&&"PM".equals(ep))return BigDecimal.ONE;return new BigDecimal("0.5");}if(!isWorking(start,method,holidays))sp="FULL";if(!isWorking(end,method,holidays))ep="FULL";if(!"FULL".equals(sp)&&days>0)days--;if(!"FULL".equals(ep)&&days>0)days--;return BigDecimal.valueOf(days).add(("FULL".equals(sp)?BigDecimal.ZERO:new BigDecimal("0.5"))).add(("FULL".equals(ep)?BigDecimal.ZERO:new BigDecimal("0.5"))).setScale(1);}
    private boolean isWorking(LocalDate d,String method,Set<LocalDate> holidays){return !("OUVRES".equals(method)?d.getDayOfWeek().getValue()>5:d.getDayOfWeek().getValue()>6)&&!holidays.contains(d);}
    private List<Map<String,Object>> overlaps(int employee,Validated v,Integer ignore){String sql="SELECT id,leave_type_id,start_date,end_date,status FROM leave_requests WHERE employee_id=? AND status IN ('en_attente','en_attente_manager','en_attente_rh','a_ajuster','approuve') AND period_start<? AND period_end>?";List<Object> args=new ArrayList<>(List.of(employee,Timestamp.valueOf(v.periodEnd()),Timestamp.valueOf(v.periodStart())));if(ignore!=null){sql+=" AND id<>?";args.add(ignore);}return jdbc.queryForList(sql,args.toArray());}
    private Map<String,Object> teamImpact(int employee,Validated v){String dept=jdbc.queryForObject("SELECT department_id FROM employees WHERE id=?",String.class,employee);int team=jdbc.queryForObject("SELECT count(*) FROM employees WHERE department_id=? AND status='actif'",Integer.class,dept);int absent=jdbc.queryForObject("SELECT count(DISTINCT r.employee_id) FROM leave_requests r JOIN employees e ON e.id=r.employee_id WHERE e.department_id=? AND e.status='actif' AND r.employee_id<>? AND r.status IN ('en_attente','en_attente_manager','en_attente_rh','approuve') AND r.period_start<? AND r.period_end>?",Integer.class,dept,employee,Timestamp.valueOf(v.periodEnd()),Timestamp.valueOf(v.periodStart()));BigDecimal ratio=jdbc.queryForObject("SELECT team_absence_warning_ratio FROM leave_calendar_settings WHERE id=1",BigDecimal.class);return Map.of("otherEmployeesAbsent",absent,"teamSize",team,"warning",team>0&&BigDecimal.valueOf(absent+1).divide(BigDecimal.valueOf(team),4,java.math.RoundingMode.HALF_UP).compareTo(ratio)>=0,"warningRatio",ratio);}
    private int insertRequest(int employee,String actor,Validated v,boolean requiresDoc,boolean requiresRh,String reason){return jdbc.queryForObject("INSERT INTO leave_requests(employee_id,leave_type_id,start_date,end_date,total_business_days,status,start_portion,end_portion,period_start,period_end,submitted_by,requires_justification_snapshot,requires_rh_approval_snapshot,reason_detail) VALUES(?,?,?,?,?,'en_attente_manager',?,?,?,?,?,?,?,?) RETURNING id",Integer.class,employee,v.typeId(),v.start(),v.end(),v.days(),v.startPortion(),v.endPortion(),Timestamp.valueOf(v.periodStart()),Timestamp.valueOf(v.periodEnd()),actor,requiresDoc,requiresRh,blank(reason));}
    private void debitBalance(Map<String,Object> request,Authentication actor){String type=String.valueOf(request.get("leave_type_id"));if(!Boolean.TRUE.equals(type(type).get("requires_balance")))return;int employee=asInt(request.get("employee_id"));LocalDate start=((java.sql.Date)request.get("start_date")).toLocalDate(),end=((java.sql.Date)request.get("end_date")).toLocalDate();Validated v=new Validated(type,start,end,String.valueOf(request.get("start_portion")),String.valueOf(request.get("end_portion")),start.atStartOfDay(),end.plusDays(1).atStartOfDay(),(BigDecimal)request.get("total_business_days"));lockEmployee(employee);for(var part:daysByYear(v).entrySet()){int year=part.getKey();BigDecimal days=part.getValue();int changed=jdbc.update("UPDATE leave_balances SET taken_days=taken_days+?,remaining_days=remaining_days-? WHERE employee_id=? AND leave_type_id=? AND period_year=? AND remaining_days>=?",days,days,employee,type,year,days);if(changed!=1)throw new WorkflowConflictException("Le solde est devenu insuffisant avant la validation pour "+year+".");jdbc.update("INSERT INTO leave_balance_movements(employee_id,leave_type_id,period_year,request_id,movement_type,days,created_by) VALUES(?,?,?,?,'PRISE',?,?)",employee,type,year,asInt(request.get("id")),days,actor.getName());}}
    private void storeFile(int requestId,MultipartFile file,Authentication actor){if(file.getSize()>MAX_FILE||file.isEmpty())throw new IllegalArgumentException("Le justificatif doit peser au maximum 8 Mo.");String mime=file.getContentType();byte[] bytes=read(file);if(!MIMES.contains(mime)||!signature(mime,bytes))throw new IllegalArgumentException("Justificatif PDF, JPEG ou PNG invalide.");String filename=Objects.requireNonNullElse(file.getOriginalFilename(),"justificatif").replaceAll("[^A-Za-z0-9._-]","_");jdbc.update("INSERT INTO leave_request_documents(leave_request_id,filename,mime_type,file_size_bytes,encrypted_content,uploaded_by) VALUES(?,?,?,?,?,?)",requestId,filename,mime,file.getSize(),crypto.encryptBytes(bytes),actor.getName());jdbc.update("UPDATE leave_requests SET justification_file_url='encrypted-db',updated_at=CURRENT_TIMESTAMP WHERE id=?",requestId);}
    private byte[] read(MultipartFile f){try{return f.getBytes();}catch(IOException e){throw new IllegalArgumentException("Lecture du justificatif impossible.");}}
    private boolean signature(String mime,byte[] b){if("application/pdf".equals(mime))return b.length>=5&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F'&&b[4]=='-';if("image/png".equals(mime))return b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71;if("image/jpeg".equals(mime))return b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;return false;}
    private Map<String,Object> type(String id){return jdbc.query("SELECT id,name,requires_justification,requires_balance,requires_rh_approval FROM leave_types WHERE id=?",(rs,n)->{Map<String,Object> m=new HashMap<>();m.put("id",rs.getString(1));m.put("name",rs.getString(2));m.put("requires_justification",rs.getBoolean(3));m.put("requires_balance",rs.getBoolean(4));m.put("requires_rh_approval",rs.getBoolean(5));return m;},id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Type de congé inconnu."));}
    private BigDecimal balance(int employee,String type,int year){return jdbc.query("SELECT remaining_days FROM leave_balances WHERE employee_id=? AND leave_type_id=? AND period_year=?",(rs,n)->rs.getBigDecimal(1),employee,type,year).stream().findFirst().orElse(BigDecimal.ZERO);}
    private BigDecimal availableBalance(int employee,String type,int year,Integer ignore){String sql="SELECT id,start_date,end_date,start_portion,end_portion,total_business_days FROM leave_requests WHERE employee_id=? AND leave_type_id=? AND start_date<=? AND end_date>=? AND status IN ('en_attente','en_attente_manager','en_attente_rh','a_ajuster')";List<Object> args=new ArrayList<>(List.of(employee,type,LocalDate.of(year,12,31),LocalDate.of(year,1,1)));if(ignore!=null){sql+=" AND id<>?";args.add(ignore);}BigDecimal reserved=BigDecimal.ZERO;for(Map<String,Object> row:jdbc.queryForList(sql,args.toArray())){LocalDate a=((java.sql.Date)row.get("start_date")).toLocalDate(),b=((java.sql.Date)row.get("end_date")).toLocalDate();String sp=String.valueOf(row.get("start_portion")),ep=String.valueOf(row.get("end_portion"));Validated pending=new Validated(type,a,b,sp,ep,a.atStartOfDay(),b.plusDays(1).atStartOfDay(),(BigDecimal)row.get("total_business_days"));reserved=reserved.add(daysByYear(pending).getOrDefault(year,BigDecimal.ZERO));}return balance(employee,type,year).subtract(reserved).max(BigDecimal.ZERO);}
    private Map<Integer,BigDecimal> daysByYear(Validated v){Map<Integer,BigDecimal> result=new TreeMap<>();for(int year=v.start().getYear();year<=v.end().getYear();year++){LocalDate a=v.start().isAfter(LocalDate.of(year,1,1))?v.start():LocalDate.of(year,1,1);LocalDate b=v.end().isBefore(LocalDate.of(year,12,31))?v.end():LocalDate.of(year,12,31);if(a.isAfter(b))continue;String sp=a.equals(v.start())?v.startPortion():"FULL",ep=b.equals(v.end())?v.endPortion():"FULL";BigDecimal days=calculateDays(a,b,sp,ep);if(days.signum()>0)result.put(year,days);}return result;}
    private Map<String,Object> request(int id,int employee){return jdbc.queryForMap("SELECT r.*,t.name leave_type_name,(SELECT count(*)>0 FROM leave_request_documents d WHERE d.leave_request_id=r.id) has_document FROM leave_requests r JOIN leave_types t ON t.id=r.leave_type_id WHERE r.id=? AND r.employee_id=?",id,employee);}
    private Map<String,Object> requestForUpdate(int id){return jdbc.query("SELECT r.*,(SELECT count(*)>0 FROM leave_request_documents d WHERE d.leave_request_id=r.id) has_document FROM leave_requests r WHERE r.id=? FOR UPDATE",(rs,n)->{Map<String,Object> m=new HashMap<>();m.put("id",rs.getInt("id"));m.put("employee_id",rs.getInt("employee_id"));m.put("leave_type_id",rs.getString("leave_type_id"));m.put("start_date",rs.getDate("start_date"));m.put("end_date",rs.getDate("end_date"));m.put("start_portion",rs.getString("start_portion"));m.put("end_portion",rs.getString("end_portion"));m.put("total_business_days",rs.getBigDecimal("total_business_days"));m.put("status",rs.getString("status"));m.put("has_document",rs.getBoolean("has_document"));m.put("requires_justification_snapshot",rs.getBoolean("requires_justification_snapshot"));m.put("requires_rh_approval_snapshot",rs.getBoolean("requires_rh_approval_snapshot"));return m;},id).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Demande de congé introuvable."));}
    private void lockEmployee(int id){jdbc.queryForObject("SELECT id FROM employees WHERE id=? FOR UPDATE",Integer.class,id);}
    private int selfId(Authentication actor){if(actor==null||!access.isEmployee(actor))throw new ForbiddenOperationException("Action réservée à un compte salarié.");return jdbc.query("SELECT id FROM employees WHERE user_id=? AND status='actif'",(rs,n)->rs.getInt(1),actor.getName()).stream().findFirst().orElseThrow(()->new ForbiddenOperationException("Aucun dossier salarié actif n’est lié à ce compte."));}
    private void activeEmployee(int id){if(jdbc.queryForObject("SELECT count(*) FROM employees WHERE id=? AND status='actif'",Integer.class,id)==0)throw new ResourceNotFoundException("Salarié actif introuvable.");}
    private void requirePortalRole(Authentication a){if(a==null||(!access.isEmployee(a)&&!access.isManager(a)&&!access.isHr(a)))throw new ForbiddenOperationException("Accès au module congés refusé.");}
    private void requireApprover(Authentication a){if(a==null||(!access.isHr(a)&&!access.isManager(a)))throw new ForbiddenOperationException("Validation réservée au manager et aux RH.");}
    private void checkApproverScope(int employee,Authentication actor){activeEmployee(employee);if(access.isManager(actor)){String dept=jdbc.queryForObject("SELECT department_id FROM employees WHERE id=?",String.class,employee);access.requireDepartmentScope(actor,dept);}}
    private String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
    private int asInt(Object v){return v instanceof Number n?n.intValue():Integer.parseInt(v.toString());}
    private String blank(String v){return v==null||v.isBlank()?null:v.trim();}
    private record Validated(String typeId,LocalDate start,LocalDate end,String startPortion,String endPortion,LocalDateTime periodStart,LocalDateTime periodEnd,BigDecimal days){}
    public record LeaveFile(String filename,String mimeType,byte[] content){}
}
